244	        OwnerPageDto ownerPageDto = new OwnerPageDto();
245	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
246	        ownerPageDto.setPage(ownerPage.getNumber());
247	        ownerPageDto.setSize(ownerPage.getSize());
248	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
249	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
250	        return ownerPageDto;
251	    }
